local k={241,210,119,88,230,163,101,83,192,246,119,242,149,185,3,14,206,126,57,130,26,118,153,240,199,212,56,35,146,119,232,188}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
